    /**
     * Tests getting all DataProviders.
     *
     * @return    Collection
     */
    public List<DataProvider> testGetAll() throws Throwable {
    LOGGER.info( "DataProviderTest:testGetAll() - Retrieving Collection of DataProviders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DataProvider : " );
    List<DataProvider> collection  = null;

    try {
        // call the static get method on the DataProviderService
        collection = service.getAllDataProvider();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DataProvider currEntity  = null;
            Iterator<DataProvider> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDataProviderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

